{
    using Decayed = typename MetatypeDecay<Arg>::type;
    static constexpr bool isUsablePointer()
    {
        if constexpr (std::is_pointer_v<Decayed> && !IsPointerDeclaredOpaque<Decayed>::value)
            return is_complete<std::remove_pointer_t<Decayed>, void>::value;
        else
            return true;
    }
    enum { Value = !std::is_reference_v<Decayed> && !std::is_void_v<Decayed>
                   && is_complete<Decayed, void>::value && isUsablePointer() };
};

